// E-Ticaret Sistemi - Ana Giriş Noktası
// Main Entry Point

// Modelleri içe aktar
"src/models/user.hudhud" उपयोग;
"src/models/product.hudhud" उपयोग;
"src/models/order.hudhud" उपयोग;

// Servisleri içe aktar
"src/services/auth.hudhud" उपयोग;
"src/services/payment.hudhud" उपयोग;
"src/services/notification.hudhud" उपयोग;

// Yardımcı वर्गları içe aktar
"src/utils/validation.hudhud" उपयोग;
"src/utils/formatting.hudhud" उपयोग;

प्रिंट("============================================================");
प्रिंट("E-Ticaret Sistemi - Modüler Mimari Demo");
प्रिंट("============================================================\n");

// Servis örnekleri oluştur
चर authService = नया AuthService();
चर paymentService = नया PaymentService();
चर notificationService = नया NotificationService();

प्रिंट("1️⃣  KULLANICI KAYDI");
प्रिंट("─────────────────────────────────────────────────────────\n");

// Yeni उपयोगıcı oluştur
चर newUser = नया User("Davut Süleyman", "davut@example.com", "güvenli123");
प्रिंट("Kullanıcı oluşturuldu: " + newUser.bilgi());

// Email सत्यla
अगर (Validation.email(newUser.email)) {
    प्रिंट("✓ Email geçerli: " + newUser.email);
} नहीं_तो {
    प्रिंट("✗ Email geçersiz");
}

// Kullanıcıyı kaydet
चर authResult = authService.register(newUser);
अगर (authResult.success) {
    प्रिंट("✓ " + authResult.message + " (ID: " + authResult.userId + ")");

    // Hoş geldin bildirimi
    notificationService.send(
        newUser.email,
        "Hoş Geldiniz!",
        "Aramıza hoş geldiniz, " + newUser.name
    );
}

प्रिंट("\n2️⃣  ÜRÜN OLUŞTURMA");
प्रिंट("─────────────────────────────────────────────────────────\n");

// Ürün oluştur
चर product = नया Product("MacBook Pro M3", 45000, 10, "Elektronik");
प्रिंट("Ürün oluşturuldu: " + product.bilgi());

// Fiyat सत्यla
अगर (Validation.price(product.price)) {
    प्रिंट("✓ Fiyat geçerli: " + Formatting.currency(product.price, "TRY"));
}

// Stok kontrolü
अगर (product.inStock()) {
    प्रिंट("✓ Ürün stokta mevcut");
} नहीं_तो {
    प्रिंट("✗ Ürün stokta yok");
}

प्रिंट("\n3️⃣  SİPARİŞ OLUŞTURMA");
प्रिंट("─────────────────────────────────────────────────────────\n");

// Sipariş oluştur
चर order = नया Order(
    newUser.id,
    product.id,
    1,
    product.price
);
प्रिंट("Sipariş oluşturuldu: " + order.bilgi());

प्रिंट("\n4️⃣  ÖDEME İŞLEMİ");
प्रिंट("─────────────────────────────────────────────────────────\n");

// Ödeme işle
चर paymentResult = paymentService.process(
    order.id,
    order.totalPrice,
    "credit_card"
);

अगर (paymentResult.success) {
    प्रिंट("✓ " + paymentResult.message);
    प्रिंट("  İşlem No: " + paymentResult.transactionId);
    प्रिंट("  Tutar: " + Formatting.currency(paymentResult.amount, "TRY"));
    प्रिंट("  Yöntem: " + paymentResult.method);

    // Siparişi onayla
    order.confirm();
    प्रिंट("✓ Sipariş onaylandı: " + order.status);

    // Sipariş onay bildirimi
    notificationService.send(
        newUser.email,
        "Siparişiniz Onaylandı",
        "Sipariş numaranız: " + order.id + " - Toplam: " + Formatting.currency(order.totalPrice, "TRY")
    );
} नहीं_तो {
    प्रिंट("✗ Ödeme başarısız: " + paymentResult.error);
}

प्रिंट("\n============================================================");
प्रिंट("✓ E-Ticaret sistemi demo tamamlandı!");
प्रिंट("✓ Modüler, ölçeklenebilir ve bakımı kolay mimari");
प्रिंट("============================================================");

