// Validation Utilities - Doğrulama Fonksiyonları

वर्ग Validation {
    स्थिर फ़ंक्शन email(email) {
        // Basit email सत्यlama
        वापसी email.length > 5;
    }

    स्थिर फ़ंक्शन password(password) {
        // Şifre en az 6 karakter olmalı
        वापसी password.length >= 6;
    }

    स्थिर फ़ंक्शन price(price) {
        वापसी price > 0;
    }

    स्थिर फ़ंक्शन phone(phone) {
        // Telefon numarası सत्यlama
        वापसी phone.length == 10;
    }

    स्थिर फ़ंक्शन required(value) {
        वापसी value.length > 0;
    }
}

