// Formatting Utilities - Formatlama Fonksiyonları

वर्ग Formatting {
    स्थिर फ़ंक्शन currency(amount, currency) {
        अगर (currency == "TRY") {
            वापसी amount + " ₺";
        } नहीं_तो {
            अगर (currency == "USD") {
                वापसी "$" + amount;
            } नहीं_तो {
                अगर (currency == "EUR") {
                    वापसी "€" + amount;
                } नहीं_तो {
                    वापसी amount + " " + currency;
                }
            }
        }
    }

    स्थिर फ़ंक्शन date(date) {
        वापसी date;
    }

    स्थिर फ़ंक्शन phone(phone) {
        // (555) 123-4567 formatı
        वापसी "(" + phone + ")";
    }

    स्थिर फ़ंक्शन number(num) {
        // 1,234,567 formatı
        वापसी num;
    }
}

