// Payment Service - Ödeme Servisi

वर्ग PaymentService {
    फ़ंक्शन process(orderId, amount, method) {
        // Basitleştirilmiş ödeme işlemi
        चर success = सत्य; // Gerçekte API çağrısı yapılır

        अगर (success) {
            वापसी {
                success: सत्य,
                transactionId: "TXN_" + Math.floor(Math.random() * 100000),
                amount: amount,
                method: method,
                message: "Ödeme başarılı"
            };
        } नहीं_तो {
            वापसी {
                success: असत्य,
                error: "Ödeme başarısız"
            };
